// Independent byte-exact oracle of the derived idna model.
use std::io::Write;
fn to_lower(s: &[u8]) -> Vec<u8> {
    s.iter().map(|&b| if b.is_ascii_uppercase() { b + 32 } else { b }).collect()
}
fn strip(s: &[u8]) -> Vec<u8> {
    if s.starts_with(b"xn--") { s[4..].to_vec() } else { s.to_vec() }
}
fn pfx(s: &[u8]) -> Vec<u8> { let mut v = b"xn--".to_vec(); v.extend_from_slice(s); v }
fn main() {
    let raw: Vec<Vec<u8>> = {
        #[cfg(unix)] { use std::os::unix::ffi::OsStrExt;
            std::env::args_os().map(|a| a.as_bytes().to_vec()).collect() }
    };
    let mut d: Vec<u8> = b"multi.level.domain.name.test".to_vec();
    if raw.len() > 1 { d = raw[1].clone(); }
    let r1 = pfx(&to_lower(&d));
    let r2 = strip(&r1);
    let r3 = pfx(&d);
    let r4 = strip(&r3);
    let r5 = !d.is_empty() && d.len() <= 255;
    let r6 = { let l = b"testlabel"; !l.is_empty() && l.len() <= 63 };
    let r7 = d.iter().all(|&b| b < 0x80);
    let r8 = d.iter().any(|&b| b >= 0x80);
    let r9 = to_lower(b"MIXEDCase");
    let r10 = to_lower(&d);
    let r11 = match d.iter().rposition(|&b| b == b'.') { Some(i) => d[i+1..].to_vec(), None => d.clone() };
    let r12: i32 = d.iter().filter(|&&b| b == b'.').count() as i32 + 1;
    let o = std::io::stdout(); let mut o = std::io::BufWriter::new(o.lock());
    for v in [r1, r2, r3, r4] { o.write_all(&v).unwrap(); o.write_all(b"\n").unwrap(); }
    for b in [r5, r6, r7, r8] { o.write_all(if b { b"1" } else { b"0" }).unwrap(); o.write_all(b"\n").unwrap(); }
    for v in [r9, r10, r11] { o.write_all(&v).unwrap(); o.write_all(b"\n").unwrap(); }
    o.write_all(format!("{}\n", r12).as_bytes()).unwrap();
    o.flush().unwrap();
}
EOF
