// Deterministic LCG fuzz corpus generator: NUL-free random byte strings, one per line
// terminated by 0x0a is unsafe (bytes may contain 0a), so emit length-prefixed records.
use std::io::Write;
fn main(){
    let mut s: u64 = 0x2545F4914F6CDD1D;
    let mut next = |s: &mut u64| { *s ^= *s<<13; *s ^= *s>>7; *s ^= *s<<17; *s };
    let o = std::io::stdout(); let mut o = std::io::BufWriter::new(o.lock());
    for i in 0..4000u32 {
        let len = (next(&mut s) % 300) as usize;
        let mode = next(&mut s) % 6;
        let mut v = Vec::with_capacity(len);
        for _ in 0..len {
            let r = next(&mut s);
            let b = match mode {
                0 => b"abcdefghijklmnopqrstuvwxyz0123456789.-"[(r % 38) as usize],
                1 => b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcxyz.-_"[(r % 35) as usize],
                2 => (0x01 + (r % 0xFF)) as u8,              // any non-NUL byte
                3 => (0x80 + (r % 0x80)) as u8,              // high bytes only (invalid UTF-8)
                4 => if r % 3 == 0 { b'.' } else { (0x41 + (r % 26)) as u8 },
                _ => (0x20 + (r % 0x5F)) as u8,              // printable ASCII
            };
            v.push(b);
        }
        o.write_all(&(v.len() as u32).to_le_bytes()).unwrap();
        o.write_all(&v).unwrap();
        let _ = i;
    }
    o.flush().unwrap();
}
EOF
