// Reads the length-prefixed corpus, runs both binaries with the record as argv[1],
// and compares raw stdout bytes. Bypasses all shell quoting hazards.
use std::io::Read; use std::process::Command;
#[cfg(unix)] use std::os::unix::ffi::OsStrExt;
fn main(){
    let a = std::env::args().nth(1).unwrap();
    let b = std::env::args().nth(2).unwrap();
    let mut buf = Vec::new();
    std::fs::File::open(std::env::args().nth(3).unwrap()).unwrap().read_to_end(&mut buf).unwrap();
    let mut i = 0usize; let mut n = 0u32; let mut fail = 0u32;
    while i + 4 <= buf.len() {
        let len = u32::from_le_bytes([buf[i],buf[i+1],buf[i+2],buf[i+3]]) as usize; i += 4;
        if i + len > buf.len() { break; }
        let arg = &buf[i..i+len]; i += len;
        let os = std::ffi::OsStr::from_bytes(arg);
        let oa = Command::new(&a).arg(os).output().unwrap();
        let ob = Command::new(&b).arg(os).output().unwrap();
        n += 1;
        if oa.stdout != ob.stdout || oa.status.code() != ob.status.code() {
            fail += 1;
            if fail <= 5 { println!("MISMATCH len={} arg_hex={}", len,
                arg.iter().map(|x| format!("{:02x}",x)).collect::<String>()); }
        }
    }
    println!("=== FUZZ: {} cases, {} mismatches ===", n, fail);
}
EOF
