// Exhaustively compare every 1-byte and 2-byte (NUL-free) argument value.
use std::process::Command; use std::sync::{Arc, Mutex}; use std::thread;
#[cfg(unix)] use std::os::unix::ffi::OsStrExt;
fn run(bin: &str, arg: &[u8]) -> Vec<u8> {
    Command::new(bin).arg(std::ffi::OsStr::from_bytes(arg)).output().unwrap().stdout
}
fn main(){
    let a = Arc::new(std::env::args().nth(1).unwrap());
    let b = Arc::new(std::env::args().nth(2).unwrap());
    let bad = Arc::new(Mutex::new(Vec::<String>::new()));
    let count = Arc::new(Mutex::new(0u64));
    let mut hs = Vec::new();
    for t in 1u32..=255 {                      // shard by first byte
        let (a,b,bad,count) = (a.clone(), b.clone(), bad.clone(), count.clone());
        hs.push(thread::spawn(move || {
            let hi = t as u8; let mut local = 0u64; let mut mine = Vec::new();
            // 1-byte case
            if run(&a, &[hi]) != run(&b, &[hi]) { mine.push(format!("1byte {:02x}", hi)); }
            local += 1;
            for lo in 1u32..=255 {             // 2-byte cases
                let arg = [hi, lo as u8];
                if run(&a, &arg) != run(&b, &arg) { mine.push(format!("2byte {:02x}{:02x}", hi, lo)); }
                local += 1;
            }
            *count.lock().unwrap() += local;
            bad.lock().unwrap().extend(mine);
        }));
        if hs.len() >= 32 { for h in hs.drain(..) { h.join().unwrap(); } }
    }
    for h in hs { h.join().unwrap(); }
    let bad = bad.lock().unwrap();
    println!("=== EXHAUSTIVE 1&2-byte: {} cases, {} mismatches ===", *count.lock().unwrap(), bad.len());
    for x in bad.iter().take(20) { println!("  {}", x); }
}
EOF
